import { proEnabled } from "../lib/pro-edition.js";// Documentation Lumen. Navigation latérale (pages dans la même fenêtre) +
// catalogue Fluxo chargé dynamiquement via la commande Rust `list_actions`,
// pour que la doc des blocs reste toujours synchrone avec le moteur.
// Fallback sur la fenêtre parente (intégration en iframe dans le bureau).
const { invoke } = (window.__TAURI__ || (window.parent && window.parent.__TAURI__) || {}).core || {};

const $ = (s) => document.querySelector(s);
const $$ = (s) => Array.from(document.querySelectorAll(s));

function docLang() {
  return localStorage.getItem("lang")
    || ((navigator.language || "fr").toLowerCase().startsWith("en") ? "en" : "fr");
}

