// ===== Rappel de hub =====
// Le bureau regroupe les apps en hubs (cf. page « Les hubs du bureau »), mais la
// doc garde une page par outil : chaque page rappelle donc où le trouver. Le
// bandeau est posé APRÈS translateDocs() et fabriqué déjà traduit, pour ne pas
// repasser dans les passes de traduction par fragments.
const HUB_OF = {
  agents: ["Équipage", "Équipe"], inbox: ["Équipage", "Fil"],
  fluxo: ["Fluxo", "Designer"],
  notes: ["Muse", "Notes"], mindmap: ["Muse", "Carte"], moodboard: ["Muse", "Planche"], canvas: ["Muse", "Canevas créatif"],
  kanban: ["Tempo", "Tableau"], calendar: ["Tempo", "Agenda"],
  tables: ["Prisme", "Tables"], dataanalysis: ["Prisme", "Analyse"], ml: ["Prisme", "Modèles"],
  knowledge: ["Corpus", "Bibliothèque"], research: ["Corpus", "Enquête"],
  appstudio: ["Forge", "Studio"], editor: ["Forge", "Code"],
  podcast: ["Écho", "Podcast"], voicelab: ["Écho", "Voix"],
  games: ["Arcade", "Jeux"], aipet: ["Arcade", "Luciole"], adventure: ["Arcade", "Aventure"],
};
const HUB_EN = { "Équipage": "Crew", "Prisme": "Prism", "Écho": "Echo" };
const TAB_EN = {
  "Équipe": "Team", "Atelier": "Workshop", "Fil": "Feed", "Carte": "Map", "Planche": "Board",
  "Tableau": "Board", "Analyse": "Analysis", "Modèles": "Models", "Bibliothèque": "Library",
  "Enquête": "Investigation", "Voix": "Voices", "Jeux": "Games", "Compagnon": "Companion",
  "Aventure": "Adventure",
};

function markHubs() {
  const en = docLang() === "en";
  for (const [page, [hub, tab]] of Object.entries(HUB_OF)) {
    const section = document.querySelector(`.page[data-page="${page}"]`);
    if (!section || section.querySelector(".hub-badge")) continue;
    const h = en ? (HUB_EN[hub] || hub) : hub;
    const t = en ? (TAB_EN[tab] || tab) : tab;
    const badge = document.createElement("div");
    badge.className = "hub-badge";
    badge.innerHTML = en
      ? `<span class="hub-dot"></span>Tab <strong>${t}</strong> of the <strong>${h}</strong> hub`
      : `<span class="hub-dot"></span>Onglet <strong>${t}</strong> du hub <strong>${h}</strong>`;
    const anchor = section.querySelector("h1");
    if (anchor) anchor.insertAdjacentElement("afterend", badge);
    else section.prepend(badge);
  }
}

window.addEventListener("DOMContentLoaded", () => {
  gateProDocs();
  applyDocIcons();
  translateDocs();
  markHubs();
  wireNav();
  loadBlocks();
});

function normText(s) {
  return String(s || "").replace(/\s+/g, " ").trim();
}

function tr(s) {
  if (docLang() !== "en") return s;
  const normalized = normText(s);
  return EN[normalized] || trFragments(normalized) || s;
}

function trFragments(s) {
  let out = String(s || "");
  const fragments = EN_FRAGMENTS.slice().sort((a, b) => b[0].length - a[0].length);
  for (const [from, to] of fragments) {
    if (out === from) return to;
    out = out.split(from).join(to);
  }
  return out !== s ? out : "";
}

function translateDocs() {
  if (docLang() !== "en") return;
  document.documentElement.lang = "en";
  document.title = "Lumen — Documentation";
  document.querySelectorAll("[placeholder],[title],[aria-label]").forEach((el) => {
    for (const a of ["placeholder", "title", "aria-label"]) {
      const v = el.getAttribute(a);
      if (v) el.setAttribute(a, tr(v));
    }
  });
  // Nœuds texte déjà traduits au niveau élément : à NE PAS repasser dans la passe
  // par nœud (sinon trFragments réappliquerait des fragments sur de l'anglais —
  // ex. « Si → If » transformerait « Simple » en « Ifmple »).
  const handled = new WeakSet();
  document.querySelectorAll(".nav-group-title,.eyebrow,h1,h2,h3,p,.t,.d,.k,.v,li").forEach((el) => {
    if (el.closest("pre,code,script,style")) return;
    const key = normText(el.textContent);
    // Correspondance exacte : traduit l'élément entier (aplatit le formatage inline,
    // mais c'est voulu pour les clés pleines).
    if (EN[key]) { el.textContent = EN[key]; if (el.firstChild) handled.add(el.firstChild); return; }
    // Sinon, on n'applique les fragments au niveau élément QUE s'il n'a pas d'enfants
    // inline (<strong>, <code>, <a>…). Les éléments mixtes sont laissés à la passe
    // par nœud texte ci-dessous, qui traduit chaque nœud sans casser le formatage.
    if (el.children.length === 0) {
      const translated = trFragments(key);
      if (translated) { el.textContent = translated; if (el.firstChild) handled.add(el.firstChild); }
    }
  });
  const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
    acceptNode(n) {
      const p = n.parentNode && n.parentNode.nodeName;
      if (p === "SCRIPT" || p === "STYLE" || p === "CODE" || p === "PRE" || p === "svg" || p === "SVG") return NodeFilter.FILTER_REJECT;
      if (handled.has(n)) return NodeFilter.FILTER_REJECT;
      return normText(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    },
  });
  const nodes = [];
  while (walk.nextNode()) nodes.push(walk.currentNode);
  nodes.forEach((n) => {
    const raw = n.nodeValue;
    const leading = raw.match(/^\s*/)?.[0] || "";
    const trailing = raw.match(/\s*$/)?.[0] || "";
    const translated = tr(raw);
    if (translated !== raw) n.nodeValue = leading + translated + trailing;
  });
}

// Documentation des apps Pro : elle ne doit pas décrire des apps que ce build
// n'embarque pas. Les entrées et pages marquées `data-pro` sont retirées du DOM
// (et non seulement masquées) pour ne pas non plus ressortir dans la recherche.
async function gateProDocs() {
  // Les apps métier sont incluses dès que le build les embarque (plus de licence).
  if (await proEnabled()) return;
  document.querySelectorAll("[data-pro]").forEach((el) => el.remove());
}

// ===== Navigation =====
function wireNav() {
  $$(".nav-item").forEach((item) => {
    item.addEventListener("click", () => showPage(item.dataset.page));
  });
}

function showPage(name) {
  $$(".nav-item").forEach((i) => i.classList.toggle("active", i.dataset.page === name));
  $$(".page").forEach((p) => p.classList.toggle("active", p.dataset.page === name));
  const content = $("#content");
  if (content) content.scrollTop = 0;
}

// ===== Catalogue Fluxo =====
// Couleurs de catégorie (alignées sur le designer Fluxo, façon Apple).
const CAT_COLORS = {
  "Texte": "#0a84ff", "Nombres": "#5e5ce6", "Listes": "#ff9f0a", "Variables": "#bf5af2",
  "Web": "#30b0c7", "Système": "#8e8e93", "Scripts": "#ff375f", "IA": "#af52de",
  "Lumen": "#ff4d6d", "Fichiers": "#34c759", "Contrôle": "#ff9500", "Données": "#0a84ff",
};
// Ordre d'affichage des catégories (les plus utilisées d'abord).
const CAT_ORDER = ["Contrôle", "Texte", "Nombres", "Listes", "Variables", "Web", "Fichiers", "Données", "Système", "Scripts", "IA", "Lumen"];

let allBlocks = [];

async function loadBlocks() {
  let specs;
  try {
    specs = await invoke("list_actions");
  } catch (e) {
    const root = $("#blocks-root");
    if (root) root.innerHTML = `<p class="muted">${escapeHtml(tr("Catalogue indisponible"))} (${escapeHtml(e?.message || String(e))}).</p>`;
    return;
  }
  allBlocks = (specs || []).map((s) => ({
    id: s.id, name: s.name, description: s.description || "", category: s.category || "Autres",
  }));
  renderBlocks("");
  $("#block-search")?.addEventListener("input", (e) => renderBlocks(e.target.value.trim().toLowerCase()));
}

function renderBlocks(query) {
  const root = $("#blocks-root");
  if (!root) return;
  const matches = allBlocks.filter((b) =>
    !query || b.name.toLowerCase().includes(query) || b.description.toLowerCase().includes(query) || b.category.toLowerCase().includes(query)
  );
  if (!matches.length) {
    root.innerHTML = `<p class="muted">${escapeHtml(tr("Aucun bloc ne correspond à"))} « ${escapeHtml(query)} ».</p>`;
    return;
  }
  // Regroupe par catégorie, en respectant l'ordre défini.
  const byCat = {};
  for (const b of matches) (byCat[b.category] ||= []).push(b);
  const cats = Object.keys(byCat).sort((a, b) => {
    const ia = CAT_ORDER.indexOf(a), ib = CAT_ORDER.indexOf(b);
    return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
  });

  root.innerHTML = cats.map((cat) => {
    const color = CAT_COLORS[cat] || "var(--accent)";
    const blocks = byCat[cat].map((b) => `
      <div class="block">
        <div class="bt"><span class="cat-dot" style="background:${color}"></span>${escapeHtml(tr(b.name))}<span class="bid">${escapeHtml(b.id)}</span></div>
        <div class="bd">${escapeHtml(tr(b.description))}</div>
      </div>`).join("");
    const count = byCat[cat].length;
    return `
      <div class="cat">
        <div class="cat-head"><span class="cat-dot" style="background:${color}"></span><h2>${escapeHtml(tr(cat))}</h2><span class="cat-count">${count} ${escapeHtml(count > 1 ? tr("blocs") : tr("bloc"))}</span></div>
        <div class="block-grid">${blocks}</div>
      </div>`;
  }).join("");
}

function escapeHtml(s) {
  return String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}


// Les icônes de la doc sont déclarées par `data-icon` et résolues ici, depuis le
// jeu partagé (lib/icons.js). Avant, chaque glyphe était dessiné à la main dans
// le HTML, avec sa propre graisse — 83 SVG au total.
function applyDocIcons() {
  document.querySelectorAll("[data-icon]").forEach((el) => {
    if (!el.firstElementChild) el.innerHTML = lumenIcon(el.dataset.icon);
  });
}
